nextflow_process {

    name "Test Process PHAROKKA_PHAROKKA"
    script "../main.nf"
    process "PHAROKKA_PHAROKKA"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "pharokka"
    tag "pharokka/pharokka"
    tag "pharokka/installdatabases"

    test("sarscov2 - genome - fasta") {
        setup {
            run("PHAROKKA_INSTALLDATABASES") {
                script "../../installdatabases/main.nf"
            }
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = PHAROKKA_INSTALLDATABASES.out.pharokka_db
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["cds_final_merged_output"])).match()}
            )
        }
    }

    test("sarscov2 - genome - fasta -- stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }
}
